from pathlib import Path
import json, html, re, math
from urllib.parse import quote
ROOT=Path(__file__).parent
D=json.loads((ROOT/'content.json').read_text())
def e(s): return html.escape(str(s),quote=True)
def img(src,alt,cls='',eager=False):return f'<img src="{e(src)}" alt="{e(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async">'
CATS={'Уход':'Уход и полив','Освещение':'Свет','Размножение':'Размножение','Цветение':'Цветение','Болезни':'Здоровье растений','Пересадка':'Грунт и пересадка','Грунт':'Грунт и пересадка','Разнообразие':'Знакомство с фиалками','Преимущества':'Знакомство с фиалками','Обработка':'Здоровье растений','Сорта':'Сорта и особенности'}
for i,a in enumerate(D['articles']):
 a.setdefault('id',f'article-{i+1:02}')
 a['category']=CATS.get(a['tag'],a['tag'])
 a['minutes']=max(1,math.ceil(len(a['text'].split())/180))
 a['url']='articles/'+a['id']+'.html'

def shell(title,body,page='home',desc='Миниатюрные фиалки из коллекции Натальи Тыриной. Каталог сортов и личный опыт ухода за растениями.',prefix=''):
 nav=[('home','index.html','Главная'),('collection','collection.html','Коллекция'),('articles','articles.html','Статьи и уход'),('about','about.html','О коллекции')]
 links=''.join(f'<a href="{prefix}{url}" {"aria-current=page" if key==page else ""}>{label}</a>' for key,url,label in nav)
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} — Фиалковая страсть</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#f7f8fa"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="{'article' if prefix else 'website'}"><link rel="icon" href="{prefix}favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}style.css"><script src="{prefix}app.js" defer></script></head><body><a class="skip" href="#main">Перейти к содержанию</a><header class="header"><div class="wrap header-inner"><a class="brand" href="{prefix}index.html"><span class="brand-icon" aria-hidden="true">✳</span><span>Фиалковая<span class="brand-sub">страсть</span></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Меню <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Основная навигация">{links}<a class="nav-contact" href="{prefix}about.html#contacts">Связаться <span aria-hidden="true">↗</span></a></nav></div></header><main id="main">{body}</main><footer><div class="wrap footer-inner"><a class="brand" href="{prefix}index.html"><span class="brand-icon" aria-hidden="true">✳</span><span>Фиалковая<span class="brand-sub">страсть</span></span></a><p>Маленькие растения. Большая любовь.<br><span>Коллекция Натальи Тыриной · Рязань</span></p><a href="https://vk.com/fialokovaya_strast" target="_blank" rel="noopener">Мы ВКонтакте ↗</a></div><div class="wrap footer-bottom">© Фиалковая страсть <span>Фотографии и опыт из личной коллекции</span></div></footer></body></html>'''
def write(name,text):
 p=ROOT/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
def article_card(a,prefix=''):
 cover=a.get('images',[])
 visual=img(prefix+cover[0],a['title']) if cover else f'<div class="article-art art-{D["articles"].index(a)%4}" aria-hidden="true"><span>✳</span><small>ЗАМЕТКИ КОЛЛЕКЦИОНЕРА</small></div>'
 return f'''<article class="article-card" data-category="{e(a['category'])}" data-search="{e((a['title']+' '+a.get('short','')+' '+a['text']).lower())}"><a class="article-cover" href="{prefix}{a['url']}" tabindex="-1" aria-hidden="true">{visual}</a><div class="article-copy"><div class="meta"><span>{e(a['category'])}</span><span>{a['minutes']} мин чтения</span></div><h3><a href="{prefix}{a['url']}">{e(a['title'])}</a></h3><p>{e(a.get('short',''))}</p><a class="text-link" href="{prefix}{a['url']}">Читать статью <span aria-hidden="true">↗</span></a></div></article>'''
def plant_card(v,i):
 return f'''<article class="plant-card" data-search="{e((v['name']+' '+v['desc']).lower())}" data-name="{e(v['name'])}"><a class="plant-photo" href="plants/plant-{i+1:02}.html">{img(v['img'],v['name'])}<span class="photo-label">Личная коллекция</span></a><div class="plant-copy"><span class="eyebrow">МИНИАТЮРНЫЕ ФИАЛКИ</span><h3><a href="plants/plant-{i+1:02}.html">{e(v['name'])}</a></h3><div class="plant-bottom"><a class="text-link" href="plants/plant-{i+1:02}.html">О сорте ↗</a><button class="favorite" data-favorite="{e(v['name'])}" aria-pressed="false" aria-label="В избранное: {e(v['name'])}">♡</button></div></div></article>'''

hero=f'''<section class="hero wrap"><div class="hero-copy"><div class="eyebrow"><span class="status-dot"></span> ЖИВАЯ КОЛЛЕКЦИЯ · РЯЗАНЬ</div><h1>Маленькие<br>фиалки.<br><span>Большая любовь.</span></h1><p class="lead">Мир миниатюрных фиалок Натальи Тыриной.<br>Выбирайте свой сорт и открывайте искусство<br class="desktop"> заботы о маленьком растении.</p><div class="actions"><a class="button primary" href="collection.html">В коллекцию <span>↗</span></a><a class="button secondary" href="articles.html">Статьи об уходе <span>→</span></a></div><div class="hero-note"><span class="tiny-flower">✳</span><span>Выращено с заботой.<br><strong>Все фотографии — мои.</strong></span></div></div><div class="hero-visual">{img('images/HuntersControlledChaos.webp','Цветущая мини-фиалка Hunters Controlled Chaos','hero-photo',True)}<div class="hero-top"><span class="glass-label">БОТАНИКА В МИНИАТЮРЕ</span><span class="image-index">01 / {len(D["violets"])}</span></div><div class="specimen"><div><span class="eyebrow">ЗНАКОМЬТЕСЬ С СОРТОМ</span><h2>Hunters Controlled Chaos</h2><span>Из личной коллекции Натальи</span></div><a href="plants/plant-15.html" aria-label="Подробнее о Hunters Controlled Chaos">↗</a></div><span class="orbit-label" aria-hidden="true">МАЛЕНЬКИЙ МИР, КОТОРЫЙ ВДОХНОВЛЯЕТ</span></div></section><div class="wrap"><div class="benefits"><div><span>01</span><p><strong>Только мини-фиалки</strong>Особенная коллекция небольших растений</p></div><div><span>02</span><p><strong>Опыт из первых рук</strong>Советы, проверенные на своих фиалках</p></div><div><span>03</span><p><strong>Доставка по России</strong>Условия отправки обсудим лично</p></div></div></div>'''
featured=''.join(plant_card(D['violets'][i],i) for i in [1,7,3,4])
home=hero+f'''<section class="section wrap"><div class="section-head"><div><div class="eyebrow">01 / КОЛЛЕКЦИЯ</div><h2>У каждой — свой характер</h2><p>Познакомьтесь с сортами, которые живут у меня.</p></div><a class="button secondary" href="collection.html">Все {len(D['violets'])} сортов ↗</a></div><div class="plant-grid">{featured}</div></section><section class="knowledge"><div class="wrap section"><div class="section-head"><div><div class="eyebrow">02 / БАЗА ЗНАНИЙ</div><h2>Забота начинается<br>с понимания</h2><p>Простые ответы и личный опыт выращивания.</p></div><a class="button secondary" href="articles.html">Все {len(D['articles'])} статей ↗</a></div><div class="article-grid">{''.join(article_card(D['articles'][i]) for i in [0,8,2])}</div></div></section><section class="wrap section"><div class="contact-banner"><div class="eyebrow">ДАВАЙТЕ ЗНАКОМИТЬСЯ</div><h2>Ваша первая мини-фиалка?<br>Помогу с выбором.</h2><p>Напишите мне: обсудим сорта, наличие и уход.</p><a class="button light" href="https://vk.com/fialokovaya_strast" target="_blank" rel="noopener">Написать ВКонтакте ↗</a><span aria-hidden="true" class="banner-flower">✳</span></div></section>'''
write('index.html',shell('Миниатюрные фиалки и забота о них',home))

cats=list(dict.fromkeys(a['category'] for a in D['articles']))
filters='<button class="chip active" data-category-filter="all" aria-pressed="true">Все статьи <span>'+str(len(D["articles"]))+'</span></button>'+''.join(f'<button class="chip" data-category-filter="{e(c)}" aria-pressed="false">{e(c)} <span>{sum(a["category"]==c for a in D["articles"])}</span></button>' for c in cats)
body=f'''<section class="wrap page-intro"><div class="eyebrow">ОПЫТ КОЛЛЕКЦИОНЕРА</div><h1>Статьи <span>и уход</span></h1><p class="lead">От первого листочка до цветущей розетки.<br>Всё, что я узнала о мини-фиалках на практике.</p></section><section class="wrap archive section-bottom" data-archive="articles"><div class="search-row"><label class="search"><span aria-hidden="true">⌕</span><input id="article-search" type="search" placeholder="Например, полив или пересадка" aria-label="Поиск по названию и тексту статей"></label><button class="reset button secondary" type="button">Сбросить</button></div><div class="filter-label">Выберите тему</div><div class="chips" aria-label="Категории статей">{filters}</div><div class="results-line"><p id="result-count" aria-live="polite">Найдено статей: {len(D["articles"])}</p><span>Личный опыт Натальи Тыриной</span></div><div class="article-grid">{''.join(article_card(a) for a in D['articles'])}</div><div class="empty" hidden><h2>Ничего не найдено</h2><p>Попробуйте другое слово или выберите «Все статьи».</p></div></section>'''
write('articles.html',shell('Статьи и уход',body,'articles'))

body=f'''<section class="wrap page-intro"><div class="eyebrow">ЖИВАЯ КОЛЛЕКЦИЯ</div><h1>Найдите <span>свою фиалку</span></h1><p class="lead">Листовые черенки из моей коллекции, детки и стартёры.<br>Наличие и условия заказа уточняйте в сообщениях.</p></section><section class="wrap section-bottom" data-archive="plants"><div class="search-row"><label class="search"><span aria-hidden="true">⌕</span><input type="search" id="plant-search" placeholder="Название сорта или его описание" aria-label="Поиск сортов"></label><button class="reset button secondary">Сбросить</button></div><div class="chips collection-chips"><button class="chip active" data-plant-filter="all" aria-pressed="true">Все сорта</button><button class="chip" data-plant-filter="favorites" aria-pressed="false">♡ Избранное</button><a class="chip" href="#kids">Детки и стартёры ↓</a></div><div class="results-line"><p id="result-count" aria-live="polite">Сортов: {len(D["violets"])}</p><span>Авторские фотографии</span></div><div class="plant-grid">{''.join(plant_card(v,i) for i,v in enumerate(D['violets']))}</div><div class="empty" hidden><h2>Пока ничего нет</h2><p>Измените запрос или добавьте понравившиеся сорта в избранное.</p></div><section id="kids" class="kids-section"><div class="eyebrow">СЛЕДУЮЩАЯ ГЛАВА ВАШЕЙ КОЛЛЕКЦИИ</div><h2>Детки и стартёры</h2><p>Список с исходного сайта. Актуальное наличие уточняйте у Натальи.</p><div class="kids-list">{''.join(f'<span>{e(k)}</span>' for k in D['kids'])}</div><a class="button primary" href="https://vk.com/fialokovaya_strast" target="_blank" rel="noopener">Уточнить наличие ↗</a></section></section>'''
write('collection.html',shell('Коллекция мини-фиалок',body,'collection'))

for i,v in enumerate(D['violets']):
 body=f'''<div class="wrap section"><a class="text-link" href="../collection.html">← Вернуться в коллекцию</a><div class="plant-detail"><div>{img('../'+v['img'],v['name'],'detail-photo',True)}</div><div><div class="eyebrow">ЛИЧНАЯ КОЛЛЕКЦИЯ</div><h1>{e(v['name'])}</h1><p class="lead">{e(v['desc'])}</p><p>Фотография взрослой розетки из коллекции Натальи Тыриной. Возможность заказа листовых черенков, деток и стартёров уточняйте лично.</p><div class="actions"><a class="button primary" href="https://vk.com/fialokovaya_strast" target="_blank" rel="noopener">Узнать о наличии ↗</a><button class="button secondary" data-favorite="{e(v['name'])}" aria-pressed="false">♡ В избранное</button></div></div></div></div>'''
 write(f'plants/plant-{i+1:02}.html',shell(v['name'],body,'collection',v['desc'],prefix='../'))

for a in D['articles']:
 paragraphs=[p.strip() for p in re.split(r'\n\s*\n',a['text']) if p.strip()]
 text=''.join('<p>'+e(p).replace('\n','<br>')+'</p>' for p in paragraphs)
 gallery=''.join('<figure>'+img('../'+im,a['title'])+'</figure>' for im in a.get('images',[]))
 related=[x for x in D['articles'] if x!=a and x['category']==a['category']][:3]
 if not related:related=[x for x in D['articles'] if x!=a][:3]
 body=f'''<div class="reading-progress" aria-hidden="true"><span></span></div><section class="wrap article-heading"><a class="text-link" href="../articles.html?category={quote(a['category'])}">← {e(a['category'])}</a><div class="meta"><span>{e(a['category'])}</span><span>{a['minutes']} мин чтения</span></div><h1>{e(a['title'])}</h1><p class="lead">{e(a.get('short',''))}</p><div class="author"><span class="author-avatar" aria-hidden="true">НТ</span><span><strong>Наталья Тырина</strong><br>Коллекционер мини-фиалок</span><button class="button secondary" id="share-article">Скопировать ссылку ↗</button></div><p class="share-status" role="status"></p></section><div class="wrap reading-layout"><aside class="reading-aside"><span class="eyebrow">ЗАМЕТКИ КОЛЛЕКЦИОНЕРА</span><p>Личный опыт выращивания миниатюрных фиалок.</p><a href="../articles.html">Все статьи ↗</a><a href="https://vk.com/fialokovaya_strast" target="_blank" rel="noopener">Задать вопрос ↗</a></aside><article class="prose">{text}{gallery}<div class="article-end">Есть вопросы? <a href="https://vk.com/fialokovaya_strast" target="_blank" rel="noopener">Обсудим ВКонтакте ↗</a></div></article></div><section class="wrap section"><div class="section-head"><h2>Продолжить знакомство</h2><a class="text-link" href="../articles.html">Все статьи ↗</a></div><div class="article-grid">{''.join(article_card(x,'../') for x in related)}</div></section>'''
 write(a['url'],shell(a['title'],body,'articles',a.get('short',a['title']),prefix='../'))

reviews=''.join(f'<blockquote class="review"><div class="review-top"><strong>{e(r["name"])}</strong><span>{e(r["city"])}</span></div><div class="stars" aria-label="{r["rating"]} из 5">{"★"*r["rating"]}</div><p>{e(r["text"])}</p><small>{e(r["date"])}</small></blockquote>' for r in D['reviews'])
body=f'''<section class="wrap page-intro"><div class="eyebrow">РАСТЕНИЯ, КОТОРЫЕ ОБЪЕДИНЯЮТ</div><h1>Увлечение, <span>которое растёт</span></h1><p class="lead">Я Наталья Тырина, коллекционер мини-фиалок из Рязани.<br>Здесь делюсь своими растениями и опытом их выращивания.</p></section><section class="wrap about-grid"><div>{img(D['violets'][1]['img'],'Фиалка ЛЕ-Polcagris из коллекции Натальи','about-photo',True)}</div><div><div class="eyebrow">МОЯ КОЛЛЕКЦИЯ</div><h2>Маленький мир<br>на вашем подоконнике</h2><p class="lead">Специализируюсь на миниатюрных фиалках. В коллекции есть редкие и популярные сорта, каждый со своим характером.</p><p>Предлагаю листовые черенки, подрощенные детки и стартёры. Все фотографии растений на сайте сделаны мной.</p><a class="text-link" href="collection.html">Познакомиться с коллекцией ↗</a></div></section><section class="wrap section" id="reviews"><div class="section-head"><div><div class="eyebrow">ОБРАТНАЯ СВЯЗЬ</div><h2>Растения в новых домах</h2><p>Отзывы, сохранённые с предыдущей версии сайта.</p></div></div><div class="review-grid">{reviews}</div></section><section id="contacts" class="wrap section-bottom"><div class="contact-banner"><div class="eyebrow">НА СВЯЗИ · РЯЗАНЬ</div><h2>Давайте вырастим<br>что-нибудь прекрасное</h2><p>Выбор сорта, наличие и советы по уходу — напишите мне ВКонтакте.</p><a class="button light" href="https://vk.com/fialokovaya_strast" target="_blank" rel="noopener">Перейти в сообщество ↗</a><span class="banner-flower" aria-hidden="true">✳</span></div><div class="delivery"><h3>Доставка по России</h3><p>На исходном сайте указана отправка через Wildberries. Текущий способ доставки, стоимость и сроки уточняйте у Натальи перед заказом.</p></div></section>'''
write('about.html',shell('О коллекции и контакты',body,'about'))
write('favicon.svg','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="18" fill="#693dd3"/><text x="32" y="47" text-anchor="middle" fill="white" font-size="51">✳</text></svg>')
# Search source is stored in the static cards, no network requests needed.
print(f'Built {len(D["articles"])} articles and {len(D["violets"])} plant pages.')
